from nearproof import (RangeAuditor, seal_span_receipt_bundle,
    audit_span_receipt_bundle, SpanReceiptBundle, RangeFrontier)
from test_range_auditor_audit_batch import (
    CHAIN, KEY, OTHER_KEY, RANGE_1, RANGE_FROM_CP,
    RECEIPT_R1, RECEIPT_RCP, RFRONTIER_1, RFRONTIER_2, CFRONTIER_1,
    range_frontier_for, U64_MAX, RDIGEST_1)
import dataclasses

b = seal_span_receipt_bundle([RECEIPT_R1, RECEIPT_RCP], KEY)
print(type(b).__name__, b.version, b.start == b"", len(b.receipts), len(b.signature))

raw = b.to_bytes()
b2 = SpanReceiptBundle.from_bytes(raw)
assert b == b2 and b2.to_bytes() == raw
assert audit_span_receipt_bundle(b, KEY) == RFRONTIER_2
assert audit_span_receipt_bundle(raw, KEY) == RFRONTIER_2

b1 = seal_span_receipt_bundle([RECEIPT_R1], KEY)
bcp = seal_span_receipt_bundle([RECEIPT_RCP], KEY, start=RFRONTIER_1)
a = RangeAuditor(KEY)
assert a.audit_bundle(b1) is a
assert a.state == RFRONTIER_1
a.audit_bundle(bcp)
assert a.state == RFRONTIER_2

try:
    a.audit_bundle(bcp)
    print("REPLAY NOT REJECTED")
except ValueError:
    print("replay rejected ok")

try:
    RangeAuditor(KEY).audit_bundle(bcp)
    print("NONEMPTY START NOT REJECTED")
except ValueError:
    print("nonempty start rejected ok")

try:
    audit_span_receipt_bundle(b, OTHER_KEY)
    print("WRONG KEY NOT REJECTED")
except ValueError:
    print("wrong key rejected ok")

for bad in (1, "x", None, [b], object(), True):
    try:
        audit_span_receipt_bundle(bad, KEY)
        print("TYPE NOT REJECTED", repr(bad))
    except TypeError:
        pass

try: seal_span_receipt_bundle([], KEY)
except ValueError: print("empty receipts rejected ok")
try: seal_span_receipt_bundle([RECEIPT_R1], b"")
except ValueError: print("empty key rejected ok")
try: seal_span_receipt_bundle(42, KEY)
except TypeError: print("non-iterable rejected ok")
try: seal_span_receipt_bundle([RECEIPT_R1], 42)
except TypeError: print("bad key type rejected ok")

try:
    seal_span_receipt_bundle([RECEIPT_R1, RECEIPT_R1], KEY)
    print("BROKEN CHAIN NOT REJECTED")
except ValueError:
    print("broken chain rejected ok")

bad_receipts = (dataclasses.replace(RECEIPT_R1, mac=b"\x01"*32).to_bytes(),
                RECEIPT_RCP.to_bytes())
pb = SpanReceiptBundle(1, b"", bad_receipts, RFRONTIER_2.to_bytes(), b"\x00"*32)
from nearproof import _span_receipt_bundle_signature
signed = dataclasses.replace(pb, signature=_span_receipt_bundle_signature(KEY, pb))
try:
    audit_span_receipt_bundle(signed, KEY)
    print("TAMPERED RECEIPT NOT REJECTED")
except ValueError:
    print("tampered receipt rejected ok")

a2 = RangeAuditor(KEY)
a2.audit_bundle(b1)
before = a2.state
try:
    a2.audit_bundle(b1)
except ValueError:
    pass
assert a2.state is before
print("frontier unchanged after failure ok")

for bad in (b"junk", b"[1]", raw + b" ", raw.replace(b":[", b": [")):
    try:
        SpanReceiptBundle.from_bytes(bad)
        print("NONCANON NOT REJECTED", bad[:20])
    except ValueError:
        pass
print("ALL SMOKE CHECKS PASSED")
